def is_good(m_str):
    m = int(m_str)
    L = len(m_str)

    if L == 1:
        # Single-digit numbers 1-9 are good
        return m != 0

    if L == 2:
        d1 = int(m_str[0])
        d2 = int(m_str[1])
        # A 2-digit number ab is good if a|b or b|a.
        return d1 % d2 == 0 or d2 % d1 == 0

    # L >= 3: Check all possible removals
    for i in range(L):
        # Form m' by removing the digit at index i
        m_prime_str = m_str[:i] + m_str[i+1:]

        try:
            m_prime = int(m_prime_str)
        except ValueError:
            continue

        # 1. Check divisibility
        if m % m_prime == 0:
            # 2. Check if m' is good (recursive call)
            if is_good(m_prime_str):
                return True

    return False

