def get_sub_numbers(m):
    s_m = str(m)
    sub_numbers = []
    for i in range(len(s_m)):
        sub_s = s_m[:i] + s_m[i+1:]
        sub_numbers.append(int(sub_s))
    return sub_numbers

def is_good_2_digit(m):
    if 10 <= m <= 99:
        d1 = m // 10
        d2 = m % 10
        return d1 != d2 and d1 != 0 and d2 != 0 and (d1 % d2 == 0 or d2 % d1 == 0)
    return False

def is_good(m, memo={}):
    if m in memo:
        return memo[m]

    s_m = str(m)
    L = len(s_m)

    if L == 1:
        return True

    if L == 2:
        result = is_good_2_digit(m)
        memo[m] = result
        return result

    # L >= 3
    sub_numbers = get_sub_numbers(m)

    for m_prime in sub_numbers:
        if m % m_prime == 0:
            if is_good(m_prime, memo):
                memo[m] = True
                return True

    memo[m] = False
    return False

